def rotate(grid, degrees):
    if degrees == 0:
        return grid
    elif degrees == 90:
        return [[grid[row][col] for row in range(len(grid)-1,-1,-1)] for col in range(len(grid[0]))]
    elif degrees == 180:
        return [row[::-1] for row in grid[::-1]]
    elif degrees == 270:
        return [[grid[row][col] for row in range(len(grid))] for col in range(len(grid[0])-1,-1,-1)]
    return grid

def diagonal_pattern_v1(input_grid):
    """Diagonal blocks = identity, off-diagonal blocks = 180° rotation"""
    blocks = []
    for block_row in range(3):
        for block_col in range(3):
            if block_row == block_col:
                blocks.append(rotate(input_grid, 0))  # Diagonal: identity
            else:
                blocks.append(rotate(input_grid, 180))  # Off-diagonal: 180°
    return assemble_9x9(blocks)

def diagonal_pattern_v2(input_grid):
    """Block row and col parity determines rotation"""
    blocks = []
    for block_row in range(3):
        for block_col in range(3):
            # Use different rotation based on parity
            if (block_row + block_col) % 2 == 0:
                blocks.append(rotate(input_grid, 0))  # Even sum: identity
            else:
                blocks.append(rotate(input_grid, 90))  # Odd sum: 90°
    return assemble_9x9(blocks)

def pattern_v3(input_grid):
    """Only use 0° and 180° based on row+col parity"""
    blocks = []
    for block_row in range(3):
        for block_col in range(3):
            if (block_row + block_col) % 2 == 0:
                blocks.append(rotate(input_grid, 0))  # Even: identity
            else:
                blocks.append(rotate(input_grid, 180))  # Odd: 180°
    return assemble_9x9(blocks)

def assemble_9x9(blocks):
    output = []
    for block_row in range(3):
        for row_idx in range(3):
            output_row = []
            for block_col in range(3):
                for col_idx in range(3):
                    value = blocks[block_row * 3 + block_col][row_idx][col_idx]
                    output_row.append(value)
            output.append(output_row)
    return output

